-- ЕРП: таблица Партньори (Клиенти + Доставчици) + импорт от Bizzio.
-- Пусни веднъж в Supabase → SQL Editor. Idempotent (on conflict do nothing).

create table if not exists public.partners (
  id bigint generated always as identity primary key,
  kind text not null check (kind in ('customer','supplier')),
  name text not null, person text, phone text, email text,
  city text, street text, country text, vat text, note text,
  created_at timestamptz default now()
);
create unique index if not exists partners_kind_name_idx on public.partners(kind, lower(name));
alter table public.partners enable row level security;
drop policy if exists "partners auth all" on public.partners;
create policy "partners auth all" on public.partners for all to authenticated using (true) with check (true);

on conflict do nothing;

